// Joined on venture_formats.slug, not on a string built from names.
//
// Until 2026-09-20 this matched cadence rows to config rows by building
// 'content_lane_' + lane + '_' + slot. The cadence table had been migrated to
// lane 'publication' and the live subchannel slugs, while the config keys were
// still content_lane_mindmaker_live_paid and _built. Nothing matched, every
// lane hit the continue below, and this produced nothing for 26 days while the
// heartbeat reported success. A slug both sides read from the same table
// cannot drift that way.
//
// The prompts are DERIVED, never stored: the format's own mandate from
// venture_formats, the voice from system_config.content_voice_block. Storing
// either would be the second copy that caused this.
const NL='\n';
function rows(n){const o=[];for(const it of $(n).all()){const j=it.json;if(Array.isArray(j))o.push(...j);else if(j&&j.data&&Array.isArray(j.data))o.push(...j.data);else if(j&&(j.key||j.id||j.lane||j.slug))o.push(j);}return o;}
const cadence=rows('Get Cadence');
const formats=rows('Get Lane Configs');
const recent=rows('Get Recent Drafts');
const vr=rows('Get Voice Block');
const rawVoice=vr.length?vr[0].value:'';
const voice=(typeof rawVoice==='string')?rawVoice:JSON.stringify(rawVoice||'');
const bySlug={};for(const f of formats){if(f&&f.slug)bySlug[f.slug]=f;}
const DAY=86400000,now=Date.now();
function hasRecentDraft(lane,slot,iv){const cut=now-(iv||7)*DAY*0.8;return recent.some(r=>r.lane===lane&&(slot?r.lane_slot===slot:true)&&r.state!=='published'&&r.state!=='dropped'&&r.created_at&&new Date(r.created_at).getTime()>=cut);}
const due=[];
for(const cc of cadence){
  if(!['overdue','due_soon','no_data'].includes(cc.status))continue;
  if(hasRecentDraft(cc.lane,cc.slot,cc.interval_days))continue;
  const f=cc.slot?bySlug[cc.slot]:null;
  if(!f)continue;
  const mandate=String(f.mandate||'').trim();
  if(!mandate)continue;
  const research=['You are researching one piece for '+f.label+'.','','THE MANDATE decides what belongs here and what does not:',mandate,'','Find the single strongest subject that fits it right now. Cite every load-bearing fact with a url and a date. Where the record is silent say unknown rather than dropping the case, because dropping incomplete cases turns a comparison into a highlight reel of whoever published most. Hold the strongest counter-case. Return the angle plus 8 or more cited sources.'].join(NL);
  const draft=[voice,'','---','','THE FORMAT YOU ARE WRITING: '+f.label+' ('+(f.gear||'')+', '+(f.cadence_label||'')+').','','ITS MANDATE, which is the authority on what this piece is:',mandate,'','Keep the body within about 700 words so the JSON stays complete.'].join(NL);
  due.push({json:{lane:cc.lane,slot:cc.slot,interval_days:cc.interval_days,format:f.label,research_prompt:research,draft_system:draft}});
}
return due;

