const cfg=$('Plan Due Lanes').item.json;
const where=cfg.slot||cfg.lane||'unnamed lane';

// A REFUSED DRAFT IS NOT A DRAFT.
//
// On 2026-09-20 the Anthropic key hit its spend cap. Sonnet Draft carries
// neverError, so the refusal became ordinary output, flowed through here, and
// was written as two content_ideas rows titled 'Untitled draft' with an empty
// body. The old line responsible was:
//
//   let d=rj(txt)||{title:'(parse failed)',body:String(txt).slice(0,2000)};
//
// which turned every failure into a row rather than a stop. Each case below
// throws instead, so the execution goes red, the fleet monitor sees a failed
// run, and the queue stays clean. Nothing is written on a bad draft.
if($json && $json.type==='error'){
  const m=(($json.error)||{}).message||'no message given';
  throw new Error('Anthropic refused the draft for '+where+': '+m);
}
const pres=$('Perplexity Research').item.json;
const ptext=(((pres.choices||[])[0]||{}).message||{}).content||'';
if(!String(ptext).trim()){
  throw new Error('No research came back for '+where+', so there is nothing to ground a draft in.');
}
const txt=(($json.content||[])[0]||{}).text||'';
if(!String(txt).trim()){
  throw new Error('Anthropic returned no text for '+where+'.');
}
function rj(t){t=String(t).trim();if(t.startsWith('```'))t=t.split('```')[1].replace(/^json/,'').trim();try{return JSON.parse(t);}catch(e){}const i=t.indexOf('{'),j=t.lastIndexOf('}');if(i>=0&&j>i){try{return JSON.parse(t.slice(i,j+1));}catch(e){}}return null;}
const d=rj(txt);
if(!d){
  throw new Error('The draft for '+where+' did not parse as JSON. First 200 characters: '+String(txt).slice(0,200));
}
if(!String(d.title||'').trim()||!String(d.body||'').trim()){
  throw new Error('The draft for '+where+' parsed but carried no title or no body.');
}
const cites=pres.citations||[];
function slug(s){return (s||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').slice(0,50);}
const row={idea:d.title,body:d.body,lane:cfg.lane,lane_slot:cfg.slot,state:'drafting',source_type:'lane_sourcing',distribution:[],source_url:((d.sources&&d.sources[0])||cites[0]||null),source_snippet:String(ptext).slice(0,500),meta:{research:cites.slice(0,8),sources:(d.sources||cites||[]),visual_suggestion:(d.visual_suggestion||null),generated_by:'lane_sourcing',lane_format:cfg.format},concept_id:'concept:content:'+cfg.lane+':'+slug(d.title)+'-'+Date.now()};
return { insert_row: row };

// Counts what was PLANNED, not what was notionally due.
//
// Until 2026-09-20 this applied the status and recent-draft filters and stopped
// there, while Plan Due Lanes applied one more: a format must exist for the
// slot. So this wrote outcome success with lanes_due 3 on every run while the
// planner produced nothing, for 26 days, and the fleet health signal stayed
// green on a workflow doing no work. Both numbers are reported now, and a gap
// between them is issues_detected, the vocabulary the rest of the fleet
// already uses for ran-but-wrong.
function rows(n){const o=[];for(const it of $(n).all()){const j=it.json;if(Array.isArray(j))o.push(...j);else if(j&&j.data&&Array.isArray(j.data))o.push(...j.data);else if(j&&(j.key||j.id||j.lane||j.slug))o.push(j);}return o;}
const cadence=rows('Get Cadence');
const recent=rows('Get Recent Drafts');
const formats=rows('Get Lane Configs');
const bySlug={};for(const f of formats){if(f&&f.slug)bySlug[f.slug]=f;}
const DAY=86400000,now=Date.now();
function hasRecent(lane,slot,iv){const c=now-(iv||7)*DAY*0.8;return recent.some(r=>r.lane===lane&&(slot?r.lane_slot===slot:true)&&r.state!=='published'&&r.state!=='dropped'&&r.created_at&&new Date(r.created_at).getTime()>=c);}
let due=0;const missing=[];
for(const cc of cadence){
  if(!['overdue','due_soon','no_data'].includes(cc.status))continue;
  if(hasRecent(cc.lane,cc.slot,cc.interval_days))continue;
  due++;
  const f=cc.slot?bySlug[cc.slot]:null;
  if(!f||!String((f&&f.mandate)||'').trim())missing.push(cc.slot||cc.lane||'unnamed');
}
const planned=due-missing.length;
const ok=missing.length===0;
return [{json:{workflow_id:'rRAyEUs7NsY06hFy',workflow_name:'Cleo | Mindmaker OS | Content Lane Sourcing',agent_id:'cleo',run_at:new Date().toISOString(),outcome:'planned:'+planned+' due:'+due,outcome_count:planned,status:ok?'success':'issues_detected',metadata:{lanes_due:due,lanes_planned:planned,lanes_without_a_format:missing}}}];
